#!/bin/sh
# release-keygen.sh — generate the release publisher key pair (owner only).
#
# The private half stays in release-key/ (untracked); the public half is pasted
# into PUBLISHER_PUBLIC_KEY in hub/src/publisher.ts and committed. One key pair
# signs every release (v14 §4).
#
# Refuses to run in CI: a key generated by an automated job would have to be
# stored in the job, which is exactly what the invite-only scheme avoids.
set -eu

if [ -n "${CI:-}" ]; then
  echo "release-keygen: refusing to run in CI" >&2
  exit 1
fi

ROOT=$(CDPATH= cd -- "$(dirname -- "$0")/.." && pwd)
DIR=${PROTEUS_RELEASE_KEY_DIR:-"$ROOT/release-key"}
if [ -e "$DIR" ]; then
  echo "release-keygen: $DIR already exists; remove it yourself to replace the key" >&2
  exit 1
fi
mkdir -p "$DIR"
chmod 700 "$DIR"

cd "$ROOT/hub"
node --input-type=module -e '
import { writeFileSync } from "node:fs";
import { ed25519 } from "@noble/curves/ed25519.js";
const dir = process.argv[1];
const secret = ed25519.utils.randomSecretKey();
const pub = ed25519.getPublicKey(secret);
writeFileSync(`${dir}/publisher.key`, Buffer.from(secret).toString("hex") + "\n", { mode: 0o600 });
writeFileSync(`${dir}/publisher.pub`, Buffer.from(pub).toString("hex") + "\n");
console.log(Buffer.from(pub).toString("hex"));
' "$DIR"

echo "" >&2
echo "Private key: $DIR/publisher.key (keep this untracked)" >&2
echo "Paste the public half above into PUBLISHER_PUBLIC_KEY in hub/src/publisher.ts." >&2
